"use client";

import { useSubmit, useFinanceData } from "@/lib/api";
import { useState } from "react";
import { Card, Skeleton } from "@/components/finance";
import { Button } from "@/components/finance";
import { Input } from "@/components/finance";
import { usePathname } from "next/navigation";

const ScenarioPage = () => {
  const pathname = usePathname();
  const [extraPayment, setExtraPayment] = useState(0);
  const [salaryDelta, setSalaryDelta] = useState(0);
  const [bonus, setBonus] = useState(0);
  const [sipStepUp, setSipStepUp] = useState(0);
  const [data, isLoading, error] = useFinanceData<{ netWorthDelta: number; goalProbabilityDelta: number }>(`${pathname}/simulate`);

  const handleSubmit = useSubmit<{ extra_payment: number; bonus: number }>(`${pathname}/simulate`, {
    onSuccess: (data) => {
      setExtraPayment(0);
      setSalaryDelta(0);
      setBonus(0);
      setSipStepUp(0);
    },
  });

  if (isLoading) return <Skeleton />;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <Card title="Scenario Lab">
      <div className="flex flex-col gap-4">
        <div>
          <label htmlFor="extraPayment">Extra Debt Payment:</label>
          <Input
            id="extraPayment"
            type="number"
            value={extraPayment}
            onChange={(e) => setExtraPayment(Number(e.target.value))}
          />
        </div>
        <div>
          <label htmlFor="salaryDelta">Salary Delta:</label>
          <Input
            id="salaryDelta"
            type="number"
            value={salaryDelta}
            onChange={(e) => setSalaryDelta(Number(e.target.value))}
          />
        </div>
        <div>
          <label htmlFor="bonus">Bonus:</label>
          <Input
            id="bonus"
            type="number"
            value={bonus}
            onChange={(e) => setBonus(Number(e.target.value))}
          />
        </div>
        <div>
          <label htmlFor="sipStepUp">SIP Step-Up:</label>
          <Input
            id="sipStepUp"
            type="number"
            value={sipStepUp}
            onChange={(e) => setSipStepUp(Number(e.target.value))}
          />
        </div>
        <Button onClick={() => handleSubmit({ extra_payment: extraPayment, bonus: bonus })}>Simulate</Button>
      </div>
      {data && (
        <div className="flex gap-4">
          <div>
            <h3>Projected Net-Worth Delta</h3>
            <div className="h-20 bg-gray-200 rounded overflow-hidden">
              <div
                className="bg-blue-500 h-full"
                style={{ width: `${(data.netWorthDelta / 100000) * 100}%` }}
              />
            </div>
          </div>
          <div>
            <h3>Goal Probability Delta</h3>
            <div className="h-20 bg-gray-200 rounded overflow-hidden">
              <div
                className="bg-green-500 h-full"
                style={{ width: `${(data.goalProbabilityDelta / 100) * 100}%` }}
              />
            </div>
          </div>
        </div>
      )}
    </Card>
  );
};

export default ScenarioPage;
